from django.core.signing import TimestampSigner, BadSignature, SignatureExpired
from django.http import JsonResponse, HttpResponseForbidden, Http404
from django.views import View
from .models import LegalAgreement

class SignedAgreementDownloadView(View):
    def get(self, request):
        token = request.GET.get('token')
        if not token or not request.user.is_authenticated:
            return HttpResponseForbidden("Authentication and signed token required")

        signer = TimestampSigner(salt='legal-agreement-view')
        try:
            # Token payload must encode both agreement_id and authorized_user_id
            payload = signer.unsign(token, max_age=86400)
            agreement_id, authorized_user_id = payload.split(':')
        except (BadSignature, SignatureExpired, ValueError):
            return HttpResponseForbidden("Invalid or expired access token")

        if str(request.user.id) != authorized_user_id:
            return HttpResponseForbidden("Token was not issued to current user")

        try:
            agreement = LegalAgreement.objects.get(pk=agreement_id, organization=request.user.organization)
        except LegalAgreement.DoesNotExist:
            raise Http404("Agreement not found")

        return JsonResponse({
            'agreement_id': agreement.id,
            'title': agreement.title,
            'counterparty': agreement.counterparty_name,
            'confidential_terms': agreement.contract_text
        })
